      "end": "p3:L22"
    },
    {
      "item_code": "S4_DOCTOR",
      "title_raw": "마. 기타 의사의 주의사항",
      "start": "p3:L23",
      "end": "p3:L27"
    }
  ],
  "extras": [
    {
