      "statements": [
        {
          "value": "자료 없음"
        ,
          "line": "p3:L27"
        }
      ]
    ,
      "suggested_code": "EXPOSURE_EFFECT"
    ,
      "line": "p3:L27"
    },
    {
      "after_item": "S4_DOCTOR",
      "title_raw": "응급 처치자의 자기 방어",
      "reason": "필드없음",
      "statements": [
        {
          "value": "피부, 눈 또는 의복과 접촉을 피할 것. 개인 보호의를 착용하시오 (8항 참조)."
        ,
          "line": "p3:L28"
        }
      ]
    ,
      "suggested_code": "PROTECTIVE_EQUIPMENT"
    ,
